<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Grupa · '.$group['label'];?>
<div class="page-head"><div><p class="eyebrow">Administracja · Grupy</p><h1><?=Html::e($group['label'])?></h1></div><a class="button secondary" href="<?=Html::e(Url::to('/admin/groups'))?>">Wróć</a></div><?php if(isset($_GET['error'])):?><div class="alert danger">Operacja została zablokowana.</div><?php endif;?>
<section class="card section-card"><form method="post" action="<?=Html::e(Url::to('/admin/groups/'.$group['id']))?>" class="inline-review-form"><?=Csrf::field()?><label>Nazwa techniczna<input name="name" value="<?=Html::e($group['name'])?>" pattern="[a-z0-9._-]{2,100}" required></label><label>Nazwa wyświetlana<input name="label" value="<?=Html::e($group['label'])?>" maxlength="150" required></label><button class="button">Zapisz</button></form></section>
<section class="card section-card"><h2>Członkowie</h2><form method="post" action="<?=Html::e(Url::to('/admin/groups/'.$group['id'].'/members'))?>" class="inline-review-form"><?=Csrf::field()?><label>Dodaj użytkownika<input name="username" data-user-input autocomplete="off" required placeholder="username"></label><button class="button">Dodaj</button></form><?php if(!$group['members']):?><div class="empty-state"><p>Brak członków.</p></div><?php endif;?><?php foreach($group['members'] as $m):?><div class="list-row"><div><strong>@<?=Html::e($m['username'])?></strong><small><?=Html::e(trim($m['first_name'].' '.$m['last_name']))?> · <?=Html::e($m['email'])?></small></div><form method="post" action="<?=Html::e(Url::to('/admin/groups/'.$group['id'].'/members/'.$m['id'].'/remove'))?>"><?=Csrf::field()?><button class="button secondary">Usuń z grupy</button></form></div><?php endforeach;?></section>
<section class="card section-card danger-zone"><h2>Usuń grupę</h2><p class="muted">Grup systemowych nie można usunąć.</p><form method="post" action="<?=Html::e(Url::to('/admin/groups/'.$group['id'].'/delete'))?>" onsubmit="return confirm('Usunąć grupę?')"><?=Csrf::field()?><button class="button danger">Usuń grupę</button></form></section>
